SELECT DATE_TRUNC('WEEK', ends_on) AS week_start, DATE_TRUNC('MONTH', starts_on) AS activity_month, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'web' THEN 1 END), 0), 2) AS discount_pct_per_web, COUNT(*) FILTER (WHERE promo_code = 'SPRING10') AS spring10_rows, MAX(discount_pct) FILTER (WHERE promo_code = 'WELCOME5') AS welcome5_max_discount_pct FROM promotions GROUP BY DATE_TRUNC('WEEK', ends_on), DATE_TRUNC('MONTH', starts_on) HAVING MAX(discount_pct) FILTER (WHERE promo_code = 'WELCOME5') < 0 ORDER BY discount_pct_per_web;
